<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Outbox\Application\Usecase\Enqueue;

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;

/**
 * Command to enqueue a notification generated from a template.
 *
 * Consumed exclusively by EnqueueNotificationUsecase. It carries all the information needed
 * to resolve the right template, render it, and place the result in the outbox queue.
 */
class EnqueueNotificationCommand
{
    /**
     * @param array<string, mixed> $variables Variables to substitute in the template.
     *                                         Nested maps are supported and will be flattened
     *                                         to dotted-key notation (e.g. ["user" => ["name" => "Alice"]]
     *                                         becomes ["user.name" => "Alice"]).
     */
    public function __construct(
        private readonly string $templateCode,
        private readonly TemplateChannelOptions $channel,
        private readonly string $recipient,
        private readonly ?TenantRef $tenant = null,
        private readonly array $variables = [],
        private readonly bool $urgent = false,
    ) {
    }

    /** Logical template code (e.g. "LOGIN_MAGIC_LINK"). */
    public function templateCode(): string
    {
        return $this->templateCode;
    }

    /** Delivery channel used to select among templates with the same code. */
    public function channel(): TemplateChannelOptions
    {
        return $this->channel;
    }

    /** Recipient email address. */
    public function recipient(): string
    {
        return $this->recipient;
    }

    /**
     * Tenant context for template resolution and SMTP config lookup.
     * Null means the global (non-tenant-specific) template and config are used.
     */
    public function tenant(): ?TenantRef
    {
        return $this->tenant;
    }

    /** @return array<string, mixed> */
    public function variables(): array
    {
        return $this->variables;
    }

    /**
     * When true the message bypasses the scheduler and is dispatched immediately via
     * register_shutdown_function after the enqueue transaction completes.
     */
    public function isUrgent(): bool
    {
        return $this->urgent;
    }
}
